head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/libRoundPanel.js");

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/stf.js"); // showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/utils.js");

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/common.js");

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/session.js"); // 세션정보를 얻기위한 함수사용

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/list_common.js");

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/PopupCalendar.js");

// 	//----W-Craft WebSquare 변환 확인: include----//
// include("../js/controlResize.js");
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF07405.gfm";
scwin.isSetPopup = false;
scwin.vSelectYear = "";
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
/**
 * 콤보박스 값 설정
 */
$c.elw.fn_searchCode = function() {
    var url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.specyvalu.instassgn.yearlist";
    dts_BAS_YY.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_BAS_YY.reset();
    var strCbd = "";
    for (j = 1; j <= dts_BAS_YY.CountRow; j++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_BAS_YY.NameValue(j, "VALUE") + "^" + dts_BAS_YY.NameValue(j, "TEXT");
    }
    cmb_BAS_YY.CBData = strCbd;
};
scwin.fn_grdSearchCode = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SPECY_VALU_INST_CD'";
    dts_Cod.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
    dts_Cod.reset();
    strCbdReason = "' ':"; //초기값

    for (k = 1; k <= dts_Cod.CountRow; k++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        if (dts_Cod.NameValue(k, "CD_ENG_NM") == "SPECY_VALU_INST_CD") {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.NameValue(k, "VALUE") + ":" + dts_Cod.NameValue(k, "TEXT");
        }

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnProp----//
    } /*ORG SRC: grd_Grid.ColumnProp('SPECY_VALU_INST_CD', 'Data') = strCbdReason;*/ X = strCbdReason;
};
scwin.fn_list_sync = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectInstAssgnInput&inputMessageId=SPECY_VALU_ASSGN_INOUT";
        url += "&BAS_YY=" + $c.stf.getObjectValue(cmb_BAS_YY); // 연도

        dts_List.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_List.reset();
        $c.cm.ShowWin(grd_Grid);
    } else {
        var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectInstAssgnInput&inputMessageId=SPECY_VALU_ASSGN_INOUT";
        url += "&BAS_YY=" + $c.stf.getObjectValue(cmb_BAS_YY); // 연도

        dts_List2.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: reset----//
        dts_List2.reset();
        $c.cm.ShowWin(grd_List);
    }
};
scwin.fn_save = function() {
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
$c.en.fn_CheckForm = function() {
    for (var i = 1, j = dts_List.CountRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: RowStatus----//
        var status = dts_List.RowStatus(i);
        if (status == 1 || status == 3) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_List.NameValue(i, "SPECY_VALU_INST_CD") == " ") {
                alert(i + "번째행  " + "TCB기관명은 필수값입니다.");
                return false;
            }

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_List.NameValue(i, "BAS_YY") == "") {
                alert(i + "번째행  " + "연도는 필수값입니다.");
                return false;
            }

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_List.NameValue(i, "SORT_ORD") == "") {
                alert(i + "번째행  " + "배정순번은 필수값입니다.");
                return false;
            }

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_List.NameValue(i, "COL_ORD_SEQ") == "") {
                alert(i + "번째행  " + "컬럼순번은 필수값입니다.");
                return false;
            }
            var instCd, rowOrd, colOrd, basYy, instNm;
            var instCdIn, rowOrdIn, colOrdIn, instNmIn, basYyIn;

	//----W-Craft WebSquare 변환 확인: NameValue----//
            instCd = dts_List.NameValue(i, "SPECY_VALU_INST_CD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
            rowOrd = dts_List.NameValue(i, "SORT_ORD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
            colOrd = dts_List.NameValue(i, "COL_ORD_SEQ");

	//----W-Craft WebSquare 변환 확인: NameValue----//
            basYy = dts_List.NameValue(i, "BAS_YY");

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
            instNm = dts_Cod.NameValue(dts_Cod.NameValueRow("VALUE", instCd), "TEXT");
            for (var k = 1, l = dts_List.CountRow; k <= l; k++) {
                if (i == k) continue;

	//----W-Craft WebSquare 변환 확인: NameValue----//
                instCdIn = dts_List.NameValue(k, "SPECY_VALU_INST_CD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
                rowOrdIn = dts_List.NameValue(k, "SORT_ORD");

	//----W-Craft WebSquare 변환 확인: NameValue----//
                colOrdIn = dts_List.NameValue(k, "COL_ORD_SEQ");

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
                instNmIn = dts_Cod.NameValue(dts_Cod.NameValueRow("VALUE", instCdIn), "TEXT");

	//----W-Craft WebSquare 변환 확인: NameValue----//
                basYyIn = dts_List.NameValue(k, "BAS_YY");
                if (instCd == instCdIn && basYy == basYyIn) {
                    if (rowOrd == rowOrdIn) {
                        alert("'" + instNmIn + "' 중복된 배정순번이 존재합니다.");
                        return false;
                    }
                    if (colOrd != colOrdIn) {
                        alert("'" + instNmIn + "' 컬럼순번이 다른값이 존재합니다.");
                        return false;
                    }
                }
                if (instCd != instCdIn && basYy == basYyIn) {
                    if (colOrd == colOrdIn) {
                        alert("TCB기관별(" + instNm + " ," + instNmIn + ")중복된 컬럼순번이 존재합니다.");
                        return false;
                    }
                }
            }
        }
    }
    return true;
};
scwin.fn_trs = function() {
    if (TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    }
    trs_Save.Action = $c.lce.fn_encodeNSession("/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveInstAssgn");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List)";

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Save.Post();
};
scwin.fn_setGrid = function() {
    if (dts_List2.CountRow > 0) {
        dts_List3.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECY_VALU_ASSGNVIEW_INOUT";

	//----W-Craft WebSquare 변환 확인: Reset----//
        dts_List3.Reset();
    }
};
scwin.fn_setGrid2 = function() {
    for (var i = 1, j = 12; i <= j; i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnProp----//
        /*ORG SRC: grd_List.ColumnProp("COM_NM" + i, "Name") = "배정회사" + i;*/
        X = "배정회사" + i;
    }

	//----W-Craft WebSquare 변환 확인: NameMax----//
    var maxRow = dts_List2.NameMax("SORT_ORD", 0, 0);

	//----W-Craft WebSquare 변환 확인: NameMax----//
    var maxCol = dts_List2.NameMax("COL_ORD_SEQ", 0, 0);
    for (var i = 1, j = maxRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: addRow----//
        dts_List3.addRow();
    }
    for (var i = 1, j = 12; i <= j; i++) {
        if (i <= maxCol) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnProp----//
            /*ORG SRC: grd_List.ColumnProp("COM_NM" + i, "Show") = true;*/
            X = true;
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnProp----//
            /*ORG SRC: grd_List.ColumnProp("COM_NM" + i, "Show") = false;*/
            X = false;
        }
    }
    for (var k = 1, l = maxCol; k <= l; k++) {
        for (var i = 1, j = maxRow; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: NameValueRow----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
            var findRow = dts_List2.NameValueRow("MAKED_KEY", i + "_" + k);
            if (findRow > 0) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
                /*ORG SRC: dts_List3.NameValue(i, "COM_NM" + k) = dts_List2.NameValue(findRow, "ASSGN_COM_NM");*/

	//----W-Craft WebSquare 변환 확인: NameValue----//
                X = dts_List2.NameValue(findRow, "ASSGN_COM_NM");

	//----W-Craft WebSquare 변환 확인: ColumnProp----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
                var grdHeadName = grd_List.ColumnProp("COM_NM" + k, "Name"); /*ORG SRC: grd_List.ColumnProp("COM_NM" + k, "Name") = dts_List2.NameValue(findRow, "SKIL_VALU_INST_CD_NM");*/ X = dts_List2.NameValue(findRow, "SKIL_VALU_INST_CD_NM");
            }
        }
    }
    for (var i = 1, j = 12; i <= j; i++) {

	//----W-Craft WebSquare 변환 확인: ColumnProp----//
        var grdHeadName = grd_List.ColumnProp("COM_NM" + i, "Name");
        if (grdHeadName.indexOf("배정회사") > -1) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************


	//----W-Craft WebSquare 변환 확인: ColumnProp----//
            /*ORG SRC: grd_List.ColumnProp("COM_NM" + i, "Show") = false;*/
            X = false;
        }
    }
    $c.stf.FillGridHeaderTotalCnt(maxRow, panel_page);
    $c.cm.CloseWin(maxRow, grd_List);
};
scwin.btn_Search1_onclick = function(e) {
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_searchCode();
    scwin.fn_grdSearchCode();

	//----W-Craft WebSquare 변환 확인: NameValue----//
    var firstYear = dts_BAS_YY.NameValue(1, "VALUE");
    $c.stf.setObjectValue(cmb_BAS_YY, firstYear);
    scwin.vSelectYear = firstYear;
    scwin.fn_list_sync();
};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = function() {
    $c.lce.fn_alertMsg('S');
    scwin.fn_searchCode();
    if (scwin.vSelectYear == undefined && dts_BAS_YY.CountRow > 0) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
        $c.stf.setObjectValue(cmb_BAS_YY, dts_BAS_YY.NameValue(1, "VALUE"));
    }
    $c.stf.setObjectValue(cmb_BAS_YY, scwin.vSelectYear);
    scwin.fn_list_sync();
};
scwin.btn_Modify_onclick = function(e) {
    scwin.fn_save();
};
scwin.btn_Delete_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: deleterow----//
    dts_List.deleterow(dts_List.rowposition);
};
scwin.btn_New_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: addRow----//
    dts_List.addRow();
    var year = $c.stf.getObjectValue(cmb_BAS_YY);
    if (year != "") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameValue----//
        /*ORG SRC: dts_List.NameValue(dts_List.RowPosition, "BAS_YY") = year;*/
        X = year;
    }
};
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    //fn_SetPar = fn_SetInstPtnt2;
    // var wth = 1400;
    // var hgt = 830;
    // var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);

	// //----W-Craft WebSquare 변환 확인: CreateDialogFrame----//
    // frame.CreateDialogFrame("", "ULDSTF07400.gfm", "전문평가관리내역", pt.x, pt.y, wth, hgt, "window");

    var url = "/ui/lst/lstinvstg/ULDSTF07400.xml";
    var popTitle = "전문평가관리내역";

    const opts = {
        id: "ULDSTF07400",
        popupName: popTitle,
        width: 1400,
        height: 830,
        frameModal: "top",
    };

    const res = await $c.win.openPopup(url, opts);
};
scwin.cmb_BAS_YY_OnSelChange = function(info) {
    scwin.vSelectYear = $c.stf.getObjectValue(cmb_BAS_YY);
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    scwin.fn_setGrid();
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    scwin.fn_setGrid2();
};
scwin.btn_Excel_onclick = function(e) {
    if (dts_List3.CountRow > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);

	//----W-Craft WebSquare 변환 확인: GridToOffice----//
        grd_List.GridToOffice("TCB별 배정내역", "", 8, 0);
    } else {
        alert(NO_EXCEL_DATA);
    }
};
scwin.image_2_onclick = function(e) {
    if (dts_List.CountRow > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);

	//----W-Craft WebSquare 변환 확인: GridToOffice----//
        grd_Grid.GridToOffice("TCB별 배정내역 입력", "", 8, 0);
    } else {
        alert(NO_EXCEL_DATA);
    }
};
